/* BENCHMARK_DATA is prepended by the preparation script. */
(()=>{
'use strict';
const root=document.getElementById('candidate-benchmark');if(!root)return;
const D=BENCHMARK_DATA, colors=['#126c78','#bd572d','#63549a','#49803c'];
const shown=new Set(D.variants.map(v=>v.id));
const $=id=>document.getElementById(id);
const axis=$('benchmark-axis'),family=$('benchmark-family'),metric=$('benchmark-metric');
const el=(tag,attrs={},text)=>{const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=text;return n;};
const html=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
function svg(host,width,height,label){host.replaceChildren();const n=el('svg',{viewBox:`0 0 ${width} ${height}`,width,height,role:'img','aria-label':label});host.append(n);return n;}
const pct=(p,k='clear')=>100*p[k]/p.n;
function radar(){
 const host=$('benchmark-radar'),w=Math.max(280,host.clientWidth),r=Math.min(w*.275,145),h=r*2+130,cx=w/2,cy=h/2;
 const s=svg(host,w,h,'Radar chart: clear-map pass percentage across eight synthetic test axes. Exact values are in the score table.');
 const pt=(i,f)=>[cx+Math.sin(i*Math.PI/4)*r*f,cy-Math.cos(i*Math.PI/4)*r*f];
 const path=f=>D.axes.map((a,i)=>pt(i,f).join(',')).join(' ');
 for(const q of [.25,.5,.75,1]){s.append(el('polygon',{points:path(q),fill:'none',stroke:'#d4dedf','stroke-width':1}));const p=pt(0,q);s.append(el('text',{x:p[0]+5,y:p[1]+4,'font-size':10,fill:'#52696e'},Math.round(q*100)));}
 const names=[['Frequency','coverage'],['Weak-signal','level'],['Background','noise'],['Field of','view'],['Two','sources'],['Short','pulses'],['Rear','interference'],['Model','mismatch']];
 D.axes.forEach((a,i)=>{const p=pt(i,1);s.append(el('line',{x1:cx,y1:cy,x2:p[0],y2:p[1],stroke:'#d4dedf','stroke-width':1}));const label=pt(i,(r+35)/r);const t=el('text',{x:label[0],y:label[1]-5,'text-anchor':'middle','font-size':w<400?11:13,fill:'#19323a'});names[i].forEach((line,j)=>t.append(el('tspan',{x:label[0],dy:j?15:0},line)));s.append(t);});
 D.variants.forEach((v,j)=>{if(!shown.has(v.id))return;const points=D.axes.map((a,i)=>pt(i,D.scores[v.id][a.id]/100));s.append(el('polygon',{points:points.map(p=>p.join(',')).join(' '),fill:colors[j],'fill-opacity':.055,stroke:colors[j],'stroke-width':2}));points.forEach((p,i)=>{const c=el('circle',{cx:p[0],cy:p[1],r:3,fill:colors[j]});c.append(el('title',{},`${v.label} · ${D.axes[i].label}: ${D.scores[v.id][D.axes[i].id].toFixed(1)}%`));s.append(c);});});
}
function curvesFor(){return D.series.filter(s=>s.key===family.value&&shown.has(s.variant));}
function chart(){
 const host=$('benchmark-curve'),w=Math.max(280,host.clientWidth),h=300,ml=48,mr=18,mt=20,mb=49;
 const s=svg(host,w,h,`${D.curves[family.value].title}: ${metric.options[metric.selectedIndex].text}. Exact values are available below.`),series=curvesFor();
 const val=p=>metric.value==='clear'?pct(p):metric.value==='pointing'?pct(p,'pointing'):metric.value==='margin'?p.median_margin_db:p.p95_error_deg;
 const points=series.flatMap(x=>x.points),ys=points.map(val).filter(x=>x!==null&&Number.isFinite(x));
 const xs=D.series.find(x=>x.key===family.value).points.map(p=>p.x),lo=Math.min(...xs),hi=Math.max(...xs);
 let ymin=0,ymax=100;
 if(metric.value==='margin'){ymin=Math.min(-3,Math.floor(Math.min(...ys,0)/5)*5);ymax=Math.max(6,Math.ceil(Math.max(...ys,0)/5)*5);}
 if(metric.value==='error'){ymax=Math.max(5,Math.ceil(Math.max(...ys,0)/5)*5);}
 const logX=/\/(width|range)$/.test(family.value),scaleX=x=>logX?Math.log10(x):x;
 const X=x=>ml+(scaleX(x)-scaleX(lo))/(scaleX(hi)-scaleX(lo)||1)*(w-ml-mr),Y=y=>h-mb-(y-ymin)/(ymax-ymin)*(h-mb-mt);
 for(let i=0;i<=4;i++){const y=ymin+(ymax-ymin)*i/4;s.append(el('line',{x1:ml,y1:Y(y),x2:w-mr,y2:Y(y),stroke:'#dce4e5','stroke-width':1}));s.append(el('text',{x:ml-8,y:Y(y)+4,'text-anchor':'end','font-size':11,fill:'#52696e'},Number(y.toFixed(1))));}
 const ticks=xs.length<=8?xs:Array.from({length:5},(_,i)=>lo+(hi-lo)*i/4);
 ticks.forEach(x=>s.append(el('text',{x:X(x),y:h-mb+21,'text-anchor':'middle','font-size':11,fill:'#52696e'},Number(x.toFixed(2)))));
 s.append(el('text',{x:(ml+w-mr)/2,y:h-6,'text-anchor':'middle','font-size':12,fill:'#19323a'},D.curves[family.value].xlabel+(logX?' · log scale':'')));
 if(metric.value==='margin')s.append(el('line',{x1:ml,y1:Y(3),x2:w-mr,y2:Y(3),stroke:'#87989a','stroke-dasharray':'4 4','stroke-width':1}));
 series.forEach(a=>{const j=D.variants.findIndex(v=>v.id===a.variant);let path='',last=false;a.points.forEach(p=>{const y=val(p);if(y===null){last=false;return;}path+=`${last?'L':'M'}${X(p.x).toFixed(2)},${Y(y).toFixed(2)} `;last=true;});s.append(el('path',{d:path,stroke:colors[j],'stroke-width':2,fill:'none'}));if(xs.length<=20)a.points.forEach(p=>{const y=val(p);if(y!==null){const c=el('circle',{cx:X(p.x),cy:Y(y),r:2.5,fill:colors[j]});c.append(el('title',{},`${D.variants[j].label} · ${p.x}: ${y.toFixed(1)}`));s.append(c);}});});
 $('benchmark-curve-note').textContent=metric.value==='clear'?'Higher is better. Correct location plus at least 3 dB separation from distant competing hotspots.':metric.value==='pointing'?'Higher is better. This counts correct location even when competing hotspots remain almost as strong.':metric.value==='margin'?'Higher is better. Dashed line: 3 dB clarity requirement. This metric alone does not establish correct pointing.':'Lower is better. Zero-output maps are excluded from angular-error percentiles and fail the pass-rate metrics.';
 const body=$('benchmark-values');body.replaceChildren();for(const x of xs)for(const a of series){const p=a.points.find(t=>t.x===x),v=D.variants.find(v=>v.id===a.variant);const tr=html('tr');[x,v.label,`${p.clear} / ${p.n}`,`${p.pointing} / ${p.n}`,p.p95_error_deg===null?'—':p.p95_error_deg.toFixed(2)+'°',p.median_margin_db===null?'—':p.median_margin_db.toFixed(2)+' dB',p.median_peak_power.toExponential(3),p.zeros,p.clipped].forEach((value,i)=>{const td=html(i<2?'th':'td',String(value));if(i<2)td.scope='row';tr.append(td);});body.append(tr);}
}
function updateFamily(){family.replaceChildren();for(const [key,c]of Object.entries(D.curves)){if(c.axis!==axis.value)continue;const option=html('option',c.title);option.value=key;family.append(option);}updateSweep();}
function updateSweep(){
 const paired=axis.value==='multiple';metric.querySelector('option[value="error"]').disabled=paired;if(paired&&metric.value==='error')metric.value='clear';
 const concise={
 'mismatch/temperature':'Air temperature −10 to +40°C; actual sound speed changes while steering stays fixed at 343 m/s. Source −36 dBFS RMS, +10 dB SNR; target (13.4°, −7.1°), three bands × three seeds.',
 'mismatch/gain':'Independent channel gain errors: σ = 0 to 3 dB, without correction. Source −36 dBFS RMS, +10 dB SNR; target (13.4°, −7.1°), three bands × three seeds.',
 'mismatch/delay':'Independent channel timing errors: σ = 0 to 2 µs, without correction. Source −36 dBFS RMS, +10 dB SNR; target (13.4°, −7.1°), three bands × three seeds.',
 'mismatch/range':'Source distance 0.5 to 35 m; received RMS and +10 dB SNR held fixed. Tests wavefront curvature against far-field steering, not detection range. Target (13.4°, −7.1°), three bands × three seeds.'};
 $('benchmark-sweep-description').textContent=concise[family.value]||D.curves[family.value].description;chart();
}
for(const a of D.axes){const option=html('option',a.label);option.value=a.id;axis.append(option);}
D.variants.forEach((v,i)=>{const label=html('label'),input=html('input');input.type='checkbox';input.checked=true;input.setAttribute('aria-label',`Show ${v.microphones} mics, ${v.window_samples} samples, ${v.bins} bins, ${v.accumulator_width}-bit accumulator`);input.addEventListener('change',()=>{input.checked?shown.add(v.id):shown.delete(v.id);radar();chart();});const swatch=html('span');swatch.className='benchmark-swatch';swatch.style.backgroundColor=colors[i];const text=html('span',`${v.microphones} mics · ${v.window_samples} samples`),detail=html('span',`${v.bins} bins · ${v.accumulator_width}-bit accum.`),small=html('small',`${(v.gate_count/1000).toFixed(1)}k gates · ${v.observation_ms.toFixed(3)} ms`);detail.style.display='block';text.append(detail,small);label.append(input,swatch,text);$('benchmark-candidates').append(label);});
const head=html('tr');['Test axis',...D.variants.map(v=>v.label)].forEach(t=>{const th=html('th',t);th.scope='col';head.append(th);});$('benchmark-score-head').append(head);
D.axes.forEach(a=>{const tr=html('tr'),th=html('th',a.label);th.scope='row';tr.append(th);D.variants.forEach(v=>tr.append(html('td',D.scores[v.id][a.id].toFixed(1))));$('benchmark-score-rows').append(tr);});
$('benchmark-run-size').textContent=`${D.evaluation_count.toLocaleString()} scored integer-model maps plus ${D.null_evaluation_count} independent noise-only control maps. No full map sheets were added.`;
$('benchmark-null-note').textContent=`Noise-only controls: ${D.null_nonzero} / ${D.null_evaluation_count} maps have nonzero output. A normalized map always supplies a brightest point; this benchmark does not add a detector threshold or label these as detected discharges.`;
const finding=$('benchmark-findings');finding.replaceChildren();D.findings.forEach(t=>finding.append(html('li',t)));
axis.addEventListener('change',updateFamily);family.addEventListener('change',updateSweep);metric.addEventListener('change',chart);
let pending=false;new ResizeObserver(()=>{if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;if(root.getBoundingClientRect().width>0){radar();chart();}});}).observe(root);
updateFamily();radar();
if(new URLSearchParams(location.search).get('study')==='benchmark')document.querySelector('[data-experiment="benchmark"]').click();
})();
